.common-skill label{display:flex;flex-direction:row;align-items:center;justify-content:flex-start;text-align:left;gap:10px;font-weight:700;font-size:1rem;line-height:1.5;margin:0}
.common-skill label input{width:18px;height:18px;flex:0 0 18px;margin:0;accent-color:#285d91}
.common-skill p{line-height:1.6;margin:9px 0 0;text-align:left;font-size:1rem;overflow-wrap:anywhere}
.common-skill .help{font-size:.875rem;margin-top:7px}
.common-skill.is-inactive{opacity:.65}
@media(max-width:900px){.confirmed-effects-view #calculationPage{grid-template-columns:1fr}.confirmed-effects-view #unifiedResults{position:static;max-height:none;overflow:visible;grid-column:1!important;grid-row:2!important}.ark-stats{grid-template-columns:repeat(2,minmax(0,1fr))}}

/* Match the character page's dark chapter headings. */
.reference-section-heading,.reference-section-title{min-height:52px;align-items:center;padding:11px 14px;color:#fff;background:#303c4b;border-left:5px solid #62a2d0}
.reference-section-heading{flex-wrap:wrap}
.reference-section-heading h2,.reference-section-heading h3,.special-reminders h3.reference-section-title,.bonus-section h3.reference-section-title{color:#fff;font-size:1.12rem;line-height:1.35}
.reference-section-heading h2{display:flex;align-items:center;gap:10px}
